+export async function bulkDeleteUnusedV3Tags(
+  params: TBaseParams & { workspaceId: string; auditLog?: TV3AuditLog }
+): Promise<Response> {
+  const { authentication, workspaceId, auditLog, requestId, instance } = params;
+
+  const access = await requireV3WorkspaceAccess(authentication, workspaceId, "readWrite", requestId, instance);
+  if (access instanceof Response) return access;
+
+  const [tags, counts] = await Promise.all([
+    getTagsByWorkspaceId(access.workspaceId),
+    getVisibleTagCounts(authentication, access.workspaceId, access.organizationId),
+  ]);
+
+  const countByTagId = new Map(counts.map((entry) => [entry.tagId, entry.count]));
+
+  // Collect tags that are not used on any response
+  const unusedTagIds = tags
+    .filter((tag) => countByTagId.get(tag.id) === 0)
+    .map((tag) => tag.id);
+
+  if (unusedTagIds.length === 0) {
+    return successResponse({ deletedCount: 0 }, { requestId });
+  }
+
+  // Store old objects for audit log before deletion
+  const oldTags = tags.filter((tag) => countByTagId.get(tag.id) === 0);
+
+  // Delete all unused tags in a transaction
+  const result = await deleteUnusedTags(unusedTagIds);
+  if (!result.ok) {
+    return problemInternalError(requestId, "Unable to delete unused tags", instance);
+  }
+
+  if (auditLog) {
+    auditLog.organizationId = access.organizationId;
+    auditLog.targetId = unusedTagIds.join("-");
+    auditLog.oldObject = oldTags;
+  }
+
+  return successResponse({ deletedCount: result.data }, { requestId });
+}
