+export const deleteUnusedTags = async (tagIds: string[]): Promise<{ ok: true; data: number } | { ok: false; error: string }> => {
+  try {
+    const { count } = await prisma.tag.deleteMany({
+      where: {
+        id: { in: tagIds },
+      },
